import React, { createContext, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { ArrowDownLeft, ArrowRight, ArrowUpRight, BarChart3, Bell, BookOpen, Check, CheckCheck, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Clock3, Croissant, Download, ExternalLink, Facebook, Flame, Inbox as InboxIcon, LayoutDashboard, Leaf, Loader2, Menu, MessageCircle, Package, Plus, Search, Settings, ShieldCheck, ShoppingBag, Sparkles, Store, Trash2, Truck, Users, Wallet, X, AlertCircle, Pencil, RefreshCw, CalendarDays, LogOut, Smartphone, House } from 'lucide-react';
