 const [name,setName]=useState(initial?.customer_name||conversation?.customer_name||''),[customer,setCustomer]=useState(initial?.customer_id||conversation?.customer_id||''),[date,setDate]=useState(p?.due_date??initial?.due_date??data.today),[time,setTime]=useState(p?.due_time??initial?.due_time??'09:00'),[method,setMethod]=useState(p?.method==='unknown'?'':p?.method??initial?.method??'pickup'),[address,setAddress]=useState(p?.address??initial?.address??''),[notes,setNotes]=useState(p?.notes??initial?.notes??''),[items,setItems]=useState<{product_id:string;quantity:number;unit:string}[]>(p?.items.length?p.items:initial?.items.map(i=>({product_id:i.product_id,quantity:i.quantity,unit:i.unit}))||[{product_id:data.products.find(p=>p.active)?.id||'',quantity:1,unit:data.products.find(p=>p.active)?.unit||'piece'}]),[busy,setBusy]=useState(false);
